"""Syllabus configs for the ten CHART gap courses (spliced into build-syllabi.py)."""

B = "https://me5231979.github.io/Course_Library/courses"

def _c(slug, repo, title, subtitle, audience, core, skills, description,
       objectives, topics, activities, outcomes, frameworks, takelabel, voyage=False):
    aud = ("Part of the Manager Voyage program. " + audience) if voyage else audience
    return {
        "slug": slug,
        "coreSkills": core,
        "skills": skills,
        "title": title,
        "subtitle": subtitle,
        "audience": aud,
        "length": "Classroom: 90 minutes (60-minute core path). Self-paced web edition: about 45 minutes",
        "format": "Instructor-led, in person or virtual; learners join on their own devices via QR code. Private by design: exercises use roles and workflows (never names) and nothing typed is saved or transmitted",
        "group": "8 to 24 works best for the pair drills; scales larger with room votes",
        "description": description,
        "objectives": objectives,
        "topics": topics,
        "activities": activities,
        "outcomes": outcomes,
        "takehomes": [
            ("Printable cheat sheet", f"{B}/{repo}/cheatsheet.html"),
            (takelabel, f"{B}/{repo}/worksheet.html"),
            ("Self-paced web edition", f"{B}/{repo}/web/"),
        ],
        "learner": f"{B}/{repo}/",
        "facilitator": f"{B}/{repo}/facilitator/",
        "selfpaced": f"{B}/{repo}/web/",
        "frameworks": frameworks,
    }

KIRK = ("Built on Bloom's-verb objectives and instrumented with Kirkpatrick levels 1 to 3: a fist-to-five "
        "confidence check at close, a scored recap and per-section validation checks in session, and a "
        "capstone commitment card followed by a 7-day pulse and a 30-day re-poll. The facilitator edition "
        "follows an ATD runbook structure (Say, Do, Ask, Debrief, Transition) with Full 90 and Core 60 "
        "timed paths. Data rules follow Vanderbilt's approved-tool guidance and the shared traffic light: "
        "green for public or generic, yellow for internal work in approved VU tools only "
        "(ChatGPT EDU, Amplify, Copilot), red for private information about people, never.")

